const DICT = { en: EN, id: ID };

let lang = DEFAULT_LANG;

export function getLang() {
  return lang;
}

// Look a key up in the active language, then fall back to English, then to the
// key itself so a typo is visible instead of silently blank. {name} placeholders
// are filled from `vars`.
export function t(key, vars) {
  const table = DICT[lang] || DICT[DEFAULT_LANG];
  let out = table[key];
  if (out === undefined) out = DICT[DEFAULT_LANG][key];
  if (out === undefined) out = key;
  if (vars) {
    for (const name in vars) out = out.split("{" + name + "}").join(vars[name]);
  }
  return out;
}

function readStored() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved && DICT[saved] ? saved : null;
  } catch (err) {
    return null; // storage blocked (e.g. private mode) -> keep the default
  }
}

// Repaint every tagged node under `root` (defaults to the whole document).
export function applyStaticTranslations(root = document) {
  root.querySelectorAll("[data-i18n]").forEach((el) => {
    el.textContent = t(el.dataset.i18n);
  });
  root.querySelectorAll("[data-i18n-alt]").forEach((el) => {
    el.alt = t(el.dataset.i18nAlt);
  });
  root.querySelectorAll("[data-i18n-aria-label]").forEach((el) => {
    el.setAttribute("aria-label", t(el.dataset.i18nAriaLabel));
  });
  document.title = t("app.title");
}

function syncSwitcher() {
  document.querySelectorAll("[data-lang]").forEach((btn) => {
    btn.setAttribute("aria-pressed", btn.dataset.lang === lang ? "true" : "false");
  });
}

// Switch language, persist the choice and broadcast it so script.js can repaint
// the frame-dependent strings (status, hints, step caption...).
export function setLang(next, options = {}) {
  const persist = options.persist !== false;
  const silent = options.silent === true;
  lang = DICT[next] ? next : DEFAULT_LANG;
  if (persist) {
    try { localStorage.setItem(STORAGE_KEY, lang); } catch (err) { /* ignore */ }
  }
  document.documentElement.lang = lang;
  applyStaticTranslations();
  syncSwitcher();
  if (!silent) document.dispatchEvent(new CustomEvent("seiken:langchange", { detail: { lang } }));
}

// Called once from script.js: restore the saved language and wire the switcher.
export function initI18n() {
  document.querySelectorAll("[data-lang]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (btn.dataset.lang !== lang) setLang(btn.dataset.lang);
    });
  });
  setLang(readStored() || DEFAULT_LANG, { persist: false, silent: true });
}
